<?php
declare(strict_types=1); require __DIR__.'/common.php'; ls_auth();$in=ls_input();$app=ls_app_id($in);$device=ls_device($in);$changes=is_array($in['changes']??null)?$in['changes']:[];$p=ls_pdo();ls_boot_schema($p);ls_touch_device($p,$app,$device);$acks=[];$remote=[];
$p->beginTransaction();try{foreach(array_slice($changes,0,500) as $c){$cid=(string)($c['change_id']??'');$entity=substr((string)($c['entity']??''),0,120);$rid=substr((string)($c['record_id']??''),0,190);$op=(string)($c['operation']??'upsert');$base=$c['base_version']??null;if($cid===''||$entity===''||$rid==='')continue;$seen=$p->prepare('SELECT 1 FROM ls_runtime_acks WHERE app_id=? AND change_id=?');$seen->execute([$app,$cid]);if($seen->fetchColumn()){$acks[]=$cid;continue;}$cur=$p->prepare('SELECT data_json,version,updated_at,deleted FROM ls_runtime_records WHERE app_id=? AND entity=? AND record_id=? FOR UPDATE');$cur->execute([$app,$entity,$rid]);$old=$cur->fetch();if($old&&$base!==null&&$base!==''&&(string)$old['version']!==(string)$base){$remote[]=['entity'=>$entity,'record_id'=>$rid,'operation'=>$old['deleted']?'delete':'upsert','data'=>$old['data_json']?json_decode($old['data_json'],true):null,'version'=>(string)$old['version'],'updated_at'=>$old['updated_at'],'deleted'=>(bool)$old['deleted']];continue;}$ver=(int)($old['version']??0)+1;$json=$op==='delete'?null:json_encode($c['data']??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$del=$op==='delete'?1:0;$up=$p->prepare('INSERT INTO ls_runtime_records(app_id,entity,record_id,data_json,version,updated_at,deleted) VALUES(?,?,?,?,?,UTC_TIMESTAMP(),?) ON DUPLICATE KEY UPDATE data_json=VALUES(data_json),version=VALUES(version),updated_at=UTC_TIMESTAMP(),deleted=VALUES(deleted)');$up->execute([$app,$entity,$rid,$json,$ver,$del]);$ch=$p->prepare('INSERT INTO ls_runtime_changes(app_id,entity,record_id,operation,data_json,version,device_id,updated_at) VALUES(?,?,?,?,?,?,?,UTC_TIMESTAMP())');$ch->execute([$app,$entity,$rid,$op,$json,$ver,$device]);$ack=$p->prepare('INSERT INTO ls_runtime_acks(app_id,change_id,device_id,created_at) VALUES(?,?,?,UTC_TIMESTAMP())');$ack->execute([$app,$cid,$device]);$acks[]=$cid;}$p->commit();}catch(Throwable $e){$p->rollBack();ls_json(['ok'=>false,'error'=>'Falha transacional LS Sync.'],500);}ls_json(['ok'=>true,'acks'=>$acks,'changes'=>$remote,'cursor'=>ls_cursor($p,$app)]);
